import random
import unittest

from calculator import multiply, parse_duration


class MultiplyTest(unittest.TestCase):
    def test_multiply(self):
        self.assertEqual(multiply(3, 4), 12)


class ParseDurationTest(unittest.TestCase):
    def test_hours_and_minutes(self):
        self.assertEqual(parse_duration("1h30m"), 5400)

    def test_seconds_only(self):
        self.assertEqual(parse_duration("45s"), 45)

    def test_hours_only(self):
        self.assertEqual(parse_duration("2h"), 7200)

    def test_all_units(self):
        self.assertEqual(parse_duration("1h2m3s"), 3723)

    def test_invalid_inputs_raise_value_error(self):
        for bad in ["", " ", "abc", "30", "h", "1x", "1h1h", "30m1h", "-5s",
                    "1.5h", "1h 30m", " 1h", "1h\n", "1H", "+5s", "٣s", "1h30", None, 5]:
            with self.subTest(bad=bad):
                with self.assertRaises(ValueError):
                    parse_duration(bad)

    def test_generated_inputs(self):
        rng = random.Random(1234)
        units = {"h": 3600, "m": 60, "s": 1}
        for _ in range(2000):
            # valid: subset of units in order, each with a number
            chosen = [u for u in "hms" if rng.random() < 0.5]
            if chosen:
                nums = [rng.randint(0, 10**6) for _ in chosen]
                text = "".join(f"{n}{u}" for n, u in zip(nums, chosen))
                expected = sum(n * units[u] for n, u in zip(nums, chosen))
                self.assertEqual(parse_duration(text), expected)
            # arbitrary junk: must either return an int or raise ValueError
            junk = "".join(rng.choice("0123456789hmsHMS .-+x\n\t٣") for _ in range(rng.randint(0, 8)))
            try:
                result = parse_duration(junk)
            except ValueError:
                continue
            self.assertIsInstance(result, int)


if __name__ == "__main__":
    unittest.main()
